    #| Decode one terminated row's contents. FrameDecoder owns stream boundaries.
    method decode-row(Blob:D $line, Int:D :$row = 1, Int:D :$offset = 0,
                      Positive:D :$max-field-bytes = 1024 * 1024 --> DecodedRow:D) {
