grammar Classic {
    token TOP { <node> }
    token uint { <[0..9]>+ }
    token int { '-'? <[0..9]>+ }
    token node {
        <width=uint> 'x' <height=uint> ',' <x=int> ',' <y=int>
        [ ',' <pane=uint> | <horizontal> | <vertical> ]
    }
    token horizontal { '{' <node>+ % ',' '}' }
    token vertical { '[' <node>+ % ',' ']' }
}

